const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isHex = (c) =>
  c !== undefined && ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
const isAlpha = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdentStart = (c) => isAlpha(c) || c === '_'
const isIdentPart = (c) => isAlpha(c) || isDigit(c) || c === '_'

/** Maps every code point index to the line and column it sits on. */
function positionsOf(cps) {
  const lines = new Array(cps.length)
  const columns = new Array(cps.length)
  let line = 1
  let column = 1
  for (let i = 0; i < cps.length; i++) {
    lines[i] = line
    columns[i] = column
    const c = cps[i]
    if (c === '\n') {
      line += 1
      column = 1
    } else if (c === '\t') {
      column += 4 - ((column - 1) % 4)
    } else {
      column += 1
    }
  }
  return { lines, columns }
}

