  const cps = Array.from(source)
  const { lines, columns } = positionsOf(cps)
  const tokens = []
  const fail = (index, reason) => {
    const at = Math.min(index, cps.length - 1)
    throw new LexError(lines[at] ?? 1, columns[at] ?? 1, reason)
  }
  const push = (kind, start, end, value) => {
    tokens.push({
      kind,
      line: lines[start],
      column: columns[start],
      text: cps.slice(start, end).join(''),
      value,
    })
  }

