  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'
const isHex = (c) =>
  c !== undefined && ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
const isAlpha = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdentStart = (c) => isAlpha(c) || c === '_'
const isIdentPart = (c) => isAlpha(c) || isDigit(c) || c === '_'

/** Maps every code point index to the line and column it sits on. */
function positionsOf(cps) {
  const lines = new Array(cps.length)
  const columns = new Array(cps.length)
  let line = 1
  let column = 1
  for (let i = 0; i < cps.length; i++) {
    lines[i] = line
    columns[i] = column
    const c = cps[i]
    if (c === '\n') {
      line += 1
      column = 1
    } else if (c === '\t') {
      column += 4 - ((column - 1) % 4)
    } else {
      column += 1
    }
  }
  return { lines, columns }
}

export function scan(source) {
  const cps = Array.from(source)
  const { lines, columns } = positionsOf(cps)
  const tokens = []
  const fail = (index, reason) => {
    const at = Math.min(index, cps.length - 1)
    throw new LexError(lines[at] ?? 1, columns[at] ?? 1, reason)
  }
  const push = (kind, start, end, value) => {
    tokens.push({
      kind,
      line: lines[start],
      column: columns[start],
      text: cps.slice(start, end).join(''),
      value,
    })
  }

  let i = 0
  while (i < cps.length) {
    const c = cps[i]

    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      i += 1
      continue
    }

    if (c === '/' && cps[i + 1] === '/') {
      i += 2
      while (i < cps.length && cps[i] !== '\n') i += 1
      continue
    }

    if (c === '/' && cps[i + 1] === '*') {
      const start = i
      let depth = 0
      while (i < cps.length) {
        if (cps[i] === '/' && cps[i + 1] === '*') {
          depth += 1
          i += 2
        } else if (cps[i] === '*' && cps[i + 1] === '/') {
          depth -= 1
          i += 2
          if (depth === 0) break
        } else {
          i += 1
        }
      }
      if (depth !== 0) fail(start, 'unterminated block comment')
      continue
    }

    if (c === 'r' && cps[i + 1] === '"') {
      const start = i
      let j = i + 2
      while (j < cps.length && cps[j] !== '"') j += 1
      if (j >= cps.length) fail(start, 'unterminated string')
      push('rawstring', start, j + 1, cps.slice(i + 2, j).join(''))
      i = j + 1
      continue
    }

    if (isIdentStart(c)) {
      const start = i
      while (i < cps.length && isIdentPart(cps[i])) i += 1
      const text = cps.slice(start, i).join('')
      push(KEYWORDS.has(text) ? 'keyword' : 'ident', start, i)
      continue
    }

    if (isDigit(c)) {
      i = scanNumber(cps, i, push, fail)
      continue
    }

    if (c === '"') {
      i = scanString(cps, i, push, fail)
      continue
    }

    const pair = c + (cps[i + 1] ?? '')
    if (TWO_CHAR_PUNCT.includes(pair)) {
      push('punct', i, i + 2)
      i += 2
      continue
    }
    if (ONE_CHAR_PUNCT.has(c)) {
      push('punct', i, i + 1)
      i += 1
      continue
    }

    fail(i, `unexpected character ${c}`)
  }

  return tokens
}

/** Consumes a run of digits, allowing a `_` that sits between two of them. */
function digitRun(cps, i, pred) {
  while (i < cps.length) {
    if (pred(cps[i])) i += 1
    else if (cps[i] === '_' && pred(cps[i - 1]) && pred(cps[i + 1])) i += 1
    else break
  }
  return i
}

function scanNumber(cps, start, push, fail) {
  let i = start
  let bad = false

  const prefix = cps[i] === '0' ? (cps[i + 1] ?? '').toLowerCase() : ''
  const pred = prefix === 'x' ? isHex : prefix === 'b' ? isBin : prefix === 'o' ? isOct : null

  if (pred !== null) {
    i += 2
    if (!pred(cps[i])) bad = true
    else i = digitRun(cps, i, pred)
  } else {
    i = digitRun(cps, i, isDigit)
    if (cps[i] === '.' && isDigit(cps[i + 1])) {
      i = digitRun(cps, i + 1, isDigit)
    }
    if (cps[i] === 'e' || cps[i] === 'E') {
      let j = i + 1
      if (cps[j] === '+' || cps[j] === '-') j += 1
      if (isDigit(cps[j])) i = digitRun(cps, j, isDigit)
    }
  }

  let j = i
  while (j < cps.length && isIdentPart(cps[j])) j += 1
  if (bad || j > i) fail(start, `invalid number ${cps.slice(start, j).join('')}`)

  push('number', start, i)
  return i
}

function scanString(cps, start, push, fail) {
  let i = start + 1
  let value = ''
  while (true) {
    if (i >= cps.length) fail(start, 'unterminated string')
    const c = cps[i]
    if (c === '"') {
      push('string', start, i + 1, value)
      return i + 1
    }
    if (c === '\n') fail(i, 'newline in string')
    if (c !== '\\') {
      value += c
      i += 1
      continue
    }
    const esc = cps[i + 1]
    if (esc === undefined) fail(start, 'unterminated string')
    const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
    if (Object.prototype.hasOwnProperty.call(simple, esc)) {
      value += simple[esc]
      i += 2
      continue
    }
    if (esc === 'x') {
      if (!isHex(cps[i + 2]) || !isHex(cps[i + 3])) fail(i, 'invalid escape \\x')
      value += String.fromCharCode(parseInt(cps[i + 2] + cps[i + 3], 16))
      i += 4
      continue
    }
    if (esc === 'u') {
      if (cps[i + 2] !== '{' || !isHex(cps[i + 3])) fail(i, 'invalid escape \\u')
      let j = i + 3
      let hex = ''
      while (isHex(cps[j])) {
        hex += cps[j]
        j += 1
      }
      if (cps[j] !== '}' || parseInt(hex, 16) > 0x10ffff) fail(i, 'invalid escape \\u')
      value += String.fromCodePoint(parseInt(hex, 16))
      i = j + 1
      continue
    }
    fail(i, `invalid escape \\${esc}`)
  }
}
