/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, LexError } from './lexer.js'

const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  let tokens
  try {
    tokens = scan(readStdin())
  } catch (error) {
    if (!(error instanceof LexError)) throw error
    process.stderr.write(`error: ${error.line}:${error.column}: ${error.reason}\n`)
    process.exit(2)
  }

  let out = ''
  if (mode === 'tokens') {
    for (const token of tokens) {
      const body =
        token.kind === 'string' || token.kind === 'rawstring'
          ? JSON.stringify(token.value)
          : token.text
      out += `${token.line}:${token.column} ${token.kind} ${body}\n`
    }
  } else {
    for (const kind of KINDS) {
      out += `${kind} ${tokens.filter((token) => token.kind === kind).length}\n`
    }
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

main(process.argv.slice(2))
